<template>
  <div class="rv-root">
    <!-- ── Loading ──────────────────────────────────────────────────── -->
    <div v-if="loading" class="rv-loading">
      <v-progress-circular indeterminate color="primary" size="48"></v-progress-circular>
      <span>Loading your details…</span>
    </div>

    <!-- ── Load-time guard failures ─────────────────────────────────── -->
    <v-container v-else-if="loadError" class="mt-8">
      <v-alert type="error" outlined prominent border="left">
        <v-row align="center">
          <v-col class="grow">
            <div class="font-weight-bold text-h6 mb-1">Unable to Load Your Details</div>
            <div>{{ loadError }}</div>
          </v-col>
          <v-col class="shrink">
            <v-icon size="48" color="error">mdi-alert-circle-outline</v-icon>
          </v-col>
        </v-row>
      </v-alert>
    </v-container>

    <template v-else>
      <v-navigation-drawer
        app
        clipped
        permanent
        right
        class="primary darken-1 white--text"
        style="z-index: 3;"
      >
        <v-list class="white--text">
          <v-list-item>
            <v-btn class="secondary" dark small @click="goBack">
              <v-icon small left>mdi-close-circle-outline</v-icon>Cancel
            </v-btn>
            <v-spacer></v-spacer>
            <v-btn
              :disabled="saving"
              :loading="saving"
              class="success darken-1"
              dark
              small
              @click="submitForm"
            >
              <v-icon small left>mdi-content-save</v-icon>Submit
            </v-btn>
          </v-list-item>

          <v-divider color="white"></v-divider>
          <v-subheader class="white--text"><h2>Details</h2></v-subheader>

          <v-list-item>
            <v-list-item-content class="white--text">
              <v-list-item-title class="text-uppercase">
                <h4>Resignation Request</h4>
              </v-list-item-title>
              <v-list-item-subtitle class="white--text">
                Submit your resignation for review by your Supervisor,
                District HR and the PS.
              </v-list-item-subtitle>
            </v-list-item-content>
          </v-list-item>
        </v-list>
      </v-navigation-drawer>

      <v-container class="rv-form-wrap">
        <v-card outlined class="slv-card mb-5 mx-auto" max-width="720">
          <v-card-title class="primary darken-1 white--text text-uppercase font-weight-bold d-flex align-center py-3">
            <v-icon left color="white">mdi-account-arrow-right</v-icon>
            Resignation Request
          </v-card-title>
          <v-card-text class="pa-6">
            <v-alert type="info" dense outlined class="mb-5">
              <v-icon small class="mr-1">mdi-information-outline</v-icon>
              Your resignation request will be reviewed by your Supervisor,
              District HR and the PS before it takes effect.
            </v-alert>

            <v-form ref="form" v-model="valid">
              <div class="rv-field-label mb-2">REASON *</div>
              <v-select
                v-model="form.resignationReasons"
                :items="resignationReasonOptions"
                item-text="display"
                :rules="[
                  (v) => (v && v.length > 0) || 'At least one reason is required',
                ]"
                outlined
                dense
                multiple
                return-object
                chips
                small-chips
                deletable-chips
                placeholder="Select one or more reasons"
                prepend-inner-icon="mdi-clipboard-text-outline"
              ></v-select>

              <template v-if="showReasonOther">
                <div class="rv-field-label mb-2">OTHER REASON *</div>
                <v-textarea
                  v-model="form.resignationReasonOther"
                  outlined
                  dense
                  rows="3"
                  placeholder="Explain your reason for resigning"
                  :rules="[(v) => !!(v && v.trim()) || 'Please explain your reason']"
                  class="mb-4"
                ></v-textarea>
              </template>

              <div class="rv-field-label mb-2">EXPECTED RESIGNATION DATE *</div>
              <v-menu
                v-model="dateMenu"
                :close-on-content-click="false"
                offset-y
                min-width="290"
              >
                <template v-slot:activator="{ on }">
                  <v-text-field
                    v-model="form.expectedResignationDate"
                    outlined
                    dense
                    readonly
                    prepend-inner-icon="mdi-calendar"
                    placeholder="YYYY-MM-DD"
                    v-on="on"
                    :rules="[
                      (v) => !!v || 'Expected resignation date is required',
                    ]"
                  ></v-text-field>
                </template>
                <v-date-picker
                  v-model="form.expectedResignationDate"
                  @input="dateMenu = false"
                ></v-date-picker>
              </v-menu>
            </v-form>
          </v-card-text>
          <v-card-actions class="pa-4 pt-0">
            <v-btn text small @click="goBack">Cancel</v-btn>
            <v-spacer></v-spacer>
            <v-btn color="primary" small :loading="saving" :disabled="saving" @click="submitForm">
              <v-icon left small>mdi-content-save</v-icon>Submit Request
            </v-btn>
          </v-card-actions>
        </v-card>
      </v-container>
    </template>

    <v-snackbar v-model="snackbar.show" :color="snackbar.color" top right :timeout="4000">
      {{ snackbar.text }}
      <template #action="{ attrs }">
        <v-btn text v-bind="attrs" @click="snackbar.show = false">Close</v-btn>
      </template>
    </v-snackbar>
  </div>
</template>

<script>
import processQuestionnaire from "../../mixins/processQuestionnaire";
import generalMixin from "../../mixins/general";

const VS = {
  RESIGNATION_REASON:
    "http://ihris.org/fhir/ValueSet/resignation-reason-valueset",
};

export default {
  name: "ResignationRequest",
  mixins: [processQuestionnaire, generalMixin],
  props: ["queries"],

  data() {
    return {
      // POST /fhir/QuestionnaireResponse with this.fhir = { reason,
      // expectedResignationDate, resignationReasons, resignationReasonOther }
      // — maps onto ResignationRequestProfile's reason/expected-resignation-date/
      // resignation-details extensions. The coded resignation-details this
      // captures at submission time is what psReviewResignationWorkflow.js
      // later copies straight onto the departure record on PS approval,
      // rather than asking the PS to re-enter it. practitioner/status/
      // event-date/user-reference are all set server-side by
      // resignationRequestWorkflow.js.
      url: "http://ihris.org/fhir/Questionnaire/resignation-request",
      fhir: {},
      fhirId: "",
      profile:
        "http://ihris.org/fhir/StructureDefinition/resignation-request-profile",

      loading: true,
      loadError: null,

      valid: false,
      saving: false,
      dateMenu: false,

      resignationReasonOptions: [],

      form: {
        resignationReasons: [],
        resignationReasonOther: "",
        expectedResignationDate: null,
      },

      afterSaveMessage: "Resignation request submitted successfully!",
      snackbar: { show: false, text: "", color: "success" },
    };
  },

  computed: {
    // Mirrors assign-staff-role.vue's showResignationOther computed - the
    // free-text field only makes sense once "Other" is actually selected.
    showReasonOther() {
      return this.form.resignationReasons?.some((r) => r.code === "other");
    },
  },

  methods: {
    showSnackbar(text, color) {
      this.snackbar = { show: true, text, color: color || "success" };
    },

    async loadResignationReasonOptions() {
      try {
        const options = await this.$fhirutils.expand(VS.RESIGNATION_REASON);
        this.resignationReasonOptions = (options || []).map((c) => ({
          system: c.system,
          code: c.code,
          display: c.display,
        }));
      } catch (error) {
        console.error("Error loading resignation reasons:", error);
      }
    },

    goBack() {
      if (window.history.length > 1) {
        this.$router.go(-1);
      } else {
        this.$router.push("/");
      }
    },

    // Confirms the logged-in user maps to a staff Practitioner record,
    // same as the backend workflow does (Person -> ihris-practitioner-reference
    // -> Practitioner), before letting them attempt a submit.
    async loadOwnPractitioner() {
      const id = this.loggedInStaff?.practitioner;
      if (!id) {
        this.loadError =
          "Unable to confirm that you are a staff member, please contact your system administrator.";
        return;
      }
      try {
        const res = await fetch(`/fhir/Practitioner/${id}`);
        if (!res.ok) {
          this.loadError = "Unable to load your staff record.";
        }
      } catch (error) {
        console.error("Error loading practitioner:", error);
        this.loadError = "Unable to load your staff record.";
      }
    },

    async submitForm() {
      const valid = this.$refs.form.validate();
      if (!valid) {
        this.showSnackbar("Please complete all required fields.", "error");
        return;
      }

      this.saving = true;
      try {
        // ResignationRequestProfile still requires a plain-text `reason`
        // (unchanged, 1..1 MS) alongside the new structured resignation-details
        // - derive it from the picked reasons so it stays a meaningful summary
        // rather than asking the staff member to type the same thing twice.
        const reasonSummary = (this.form.resignationReasons || [])
          .map((r) => r.display)
          .join(", ");
        this.fhir = {
          reason: this.showReasonOther
            ? `${reasonSummary}: ${this.form.resignationReasonOther}`
            : reasonSummary,
          expectedResignationDate: this.form.expectedResignationDate,
          resignationReasons: this.form.resignationReasons,
          resignationReasonOther: this.showReasonOther
            ? this.form.resignationReasonOther
            : "",
        };
        const data = await this.processFHIR();
        this.showSnackbar(this.afterSaveMessage, "success");

        // processFHIR() already parses this same tag internally (to drive
        // its own optional viewPage redirect, which we don't use here since
        // this feature's view page is a /custom/... route, not a named
        // "resource_view" route) — mirror that extraction to get the newly
        // created request's Basic id so we can go straight to its view page.
        const redirectTag = data?.meta?.tag?.find(
          (tag) => tag.system === "http://ihris.org/fhir/tags/resource",
        );
        const newRequestId = redirectTag?.code?.split("/")?.[1];

        setTimeout(() => {
          if (newRequestId) {
            this.$router.push({
              path: "/custom/resignation-view",
              query: {
                path: "/lesotho/components/resignation",
                request: newRequestId,
              },
            });
          } else {
            this.goBack();
          }
        }, 300);
      } catch (error) {
        // Backend rejections (duplicate pending request, etc.) surface via
        // the processQuestionnaire mixin's own error toast
        // (this.$store.commit("setMessage", ...)) — nothing further
        // needed here.
        console.error("submitForm error:", error);
      } finally {
        this.saving = false;
      }
    },
  },

  async mounted() {
    await this.$nextTick();

    // Wait for generalMixin to finish loading loggedInStaff
    await new Promise((resolve) => {
      if (!this.loadingUserData) {
        resolve();
        return;
      }
      const unwatch = this.$watch("loadingUserData", (newValue) => {
        if (!newValue) {
          unwatch();
          resolve();
        }
      });
      setTimeout(() => {
        unwatch();
        resolve();
      }, 15000);
    });

    await Promise.all([
      this.loadOwnPractitioner(),
      this.loadResignationReasonOptions(),
    ]);
    this.loading = false;
  },
};
</script>

